<?php endif; ?></div><script>
document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('on'));document.querySelectorAll('.form').forEach(x=>x.classList.remove('on'));b.classList.add('on');document.getElementById(b.dataset.target).classList.add('on')});
if('serviceWorker'in navigator)addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));
const radioBtn=document.getElementById('radioToggle');
if(radioBtn){
 const dock=document.getElementById('audioDock'), meta=document.getElementById('audioMeta'), vol=document.getElementById('volume'), adhan=document.getElementById('adhanToggle');
 adhan.checked=localStorage.getItem('oyya_adhan')==='1';
 adhan.addEventListener('change',()=>{localStorage.setItem('oyya_adhan',adhan.checked?'1':'0');meta.textContent=adhan.checked?'تنبيه الأذان مفعّل — سيتم ربط مواقيت المدينة والصوت لاحقًا':'تنبيه الأذان متوقف';});
 let ctx=null, master=null, timer=null, playing=false, voices=[];
 function stopRadio(){if(timer){clearInterval(timer);timer=null}voices.forEach(v=>{try{v.stop()}catch(e){}});voices=[];if(master){master.gain.cancelScheduledValues(ctx.currentTime);master.gain.setTargetAtTime(0,ctx.currentTime,.05)}playing=false;radioBtn.textContent='▶';dock.classList.add('off');meta.textContent='متوقف — اضغط تشغيل للاستماع داخل OYYA';}
 function note(freq,dur=.9){const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(0,ctx.currentTime);g.gain.linearRampToValueAtTime(.08,ctx.currentTime+.05);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+dur);o.connect(g);g.connect(master);o.start();o.stop(ctx.currentTime+dur+.05);voices.push(o);}
 async function startRadio(){ctx=ctx||new(window.AudioContext||window.webkitAudioContext)();await ctx.resume();master=master||ctx.createGain();if(!master._linked){master.connect(ctx.destination);master._linked=true}master.gain.setValueAtTime(Number(vol.value),ctx.currentTime);const seq=[220,261.63,329.63,392,329.63,261.63];let i=0;note(seq[i++%seq.length]);timer=setInterval(()=>note(seq[i++%seq.length]),900);playing=true;radioBtn.textContent='❚❚';dock.classList.remove('off');meta.textContent='OYYA Radio · بث تجريبي داخل التطبيق';}
 radioBtn.addEventListener('click',()=>playing?stopRadio():startRadio());
 vol.addEventListener('input',()=>{if(master&&ctx)master.gain.setTargetAtTime(Number(vol.value),ctx.currentTime,.04)});
}
